// A user's data lives in the Postgres schema "u_<user id>". User ids are
// generated by us (accounts/users.ts) as 24 lowercase hex characters, so the
// name is always a safe identifier; anything else is refused before it can
// reach SQL.

const USER_ID = /^[a-f0-9]{24}$/;

export function isUserId(value: string): boolean {
  return USER_ID.test(value);
}

export function schemaForUser(userId: string): string {
  if (!isUserId(userId)) throw new Error("Invalid user id.");
  return `u_${userId}`;
}

/** The schema shared by all users: accounts, sessions and sign-in throttling. */
export const ACCOUNTS_SCHEMA = "cs_accounts";
